from dataclasses import dataclass
from datetime import date
from decimal import Decimal
import csv

@dataclass(frozen=True)
class PriceLine:
    sku: str
    unit_price: Decimal
    currency: str
    valid_from: date

    def __post_init__(self):
        if self.unit_price <= 0:
            raise ValueError(f"{self.sku}: price must be positive, got {self.unit_price}")

class SupplierAdapter:
    def parse(self, path: str) -> list[PriceLine]:
        raise NotImplementedError

class NordmjolAdapter(SupplierAdapter):        # semicolon CSV, comma decimals
    def parse(self, path: str) -> list[PriceLine]:
        with open(path, newline="", encoding="utf-8") as f:
            return [PriceLine(r["Artikel"], Decimal(r["Pris"].replace(",", ".")),
                              "SEK", date.fromisoformat(r["Fran"]))
                    for r in csv.DictReader(f, delimiter=";")]
